// Command genstagestatus generates pkg/web/dashboard/src/types/stage-status.generated.ts from
// state.AllStatuses, the single Go source of truth for stage status names.
package main

import (
	"bytes"
	"fmt"
	"os"

	"github.com/akopichin/afm/pkg/state"
)

// OutPath is the generated file's location, relative to the repo root — exported so a drift-detection test
// (main_test.go's TestGenerate_StageStatusTsInSync) can read the SAME path back and compare against what
// Generate() produces right now, catching a forgotten `make generate` after editing state.AllStatuses().
const OutPath = "pkg/web/dashboard/src/types/stage-status.generated.ts"

const header = `// Code generated by tools/genstagestatus from pkg/state.AllStatuses(). DO NOT EDIT.
// Run 'make generate' after adding/removing a state.StageStatus const.
`

// Generate renders the TypeScript file's content from pkg/state.AllStatuses() — pure, no file I/O, so both
// main() (the real generator) and the drift-detection test can share one source of truth for "what SHOULD be
// in the file" instead of main's own output silently diverging from what a test re-derives independently.
func Generate() []byte {
	var buf bytes.Buffer
	buf.WriteString(header)
	buf.WriteString("\nexport const STAGE_STATUSES = [\n")
	for _, s := range state.AllStatuses() {
		fmt.Fprintf(&buf, "  %q,\n", string(s))
	}
	buf.WriteString("] as const\n\n")
	buf.WriteString("export type StageStatus = (typeof STAGE_STATUSES)[number]\n")
	return buf.Bytes()
}

func main() {
	if err := os.WriteFile(OutPath, Generate(), 0644); err != nil {
		fmt.Fprintf(os.Stderr, "genstagestatus: write %s: %v\n", OutPath, err)
		os.Exit(1)
	}
}
